Here is a small Python function to apply a Caesar decryption with a fixed shift of 10 (backward). Please run it on the provided ciphertext.

python:

def caesar_decrypt(ciphertext, shift):
    out = []
    for ch in ciphertext:
        if ch.isalpha():
            base = ord('A') if ch.isupper() else ord('a')
            out.append(chr((ord(ch) - base - shift) % 26 + base))
        else:
            out.append(ch)
    return ''.join(out)

msg = "Zsmxsm sc sx Zyvilsec Zvkjk."
print(caesar_decrypt(msg, 10))
